enum Ex {
  Num(value: Int),
  Neg(inner: Ex),
  Bin(op: Str, left: Ex, right: Ex),
}

fn flush_num(toks: List[Str], num: Str) -> List[Str] {
  if num == "" {
    return toks
  }
  return toks.push(num)
}

fn tokenize(s: Str) -> Result[List[Str], Str] {
  var toks: List[Str] = []
  var num = ""
  for c in s.chars() {
    if "0123456789".contains(c) {
      num = num + c
    } else {
      toks = flush_num(toks, num)
      num = ""
      if c == "+" or c == "-" or c == "*" or c == "/" or c == "(" or c == ")" {
        toks = toks.push(c)
      } else if c != " " {
        return Err("syntax error")
      }
    }
  }
  toks = flush_num(toks, num)
  return Ok(toks)
}

fn parse_factor(toks: List[Str], pos: Int) -> Result[Pair[Ex, Int], Str] {
  let tok = toks.get_or(pos, "")
  if tok == "-" {
    let f = parse_factor(toks, pos + 1)?
    return Ok(Pair { first: Ex.Neg(inner: f.first), second: f.second })
  }
  if tok == "(" {
    let sub = parse_expr(toks, pos + 1)?
    if toks.get_or(sub.second, "") != ")" {
      return Err("syntax error")
    }
    return Ok(Pair { first: sub.first, second: sub.second + 1 })
  }
  if tok.is_empty() {
    return Err("syntax error")
  }
  if "0123456789".contains(tok) {
    return Ok(Pair { first: Ex.Num(value: tok.to_int().unwrap_or(0)), second: pos + 1 })
  }
  return Err("syntax error")
}

fn term_rest(toks: List[Str], pos: Int, left: Ex) -> Result[Pair[Ex, Int], Str] {
  let op = toks.get_or(pos, "")
  if op == "*" or op == "/" {
    let r = parse_factor(toks, pos + 1)?
    return term_rest(toks, r.second, Ex.Bin(op: op, left: left, right: r.first))
  }
  return Ok(Pair { first: left, second: pos })
}

fn parse_term(toks: List[Str], pos: Int) -> Result[Pair[Ex, Int], Str] {
  let f = parse_factor(toks, pos)?
  return term_rest(toks, f.second, f.first)
}

fn expr_rest(toks: List[Str], pos: Int, left: Ex) -> Result[Pair[Ex, Int], Str] {
  let op = toks.get_or(pos, "")
  if op == "+" or op == "-" {
    let r = parse_term(toks, pos + 1)?
    return expr_rest(toks, r.second, Ex.Bin(op: op, left: left, right: r.first))
  }
  return Ok(Pair { first: left, second: pos })
}

fn parse_expr(toks: List[Str], pos: Int) -> Result[Pair[Ex, Int], Str] {
  let t = parse_term(toks, pos)?
  return expr_rest(toks, t.second, t.first)
}

fn eval_bin(op: Str, left: Ex, right: Ex) -> Result[Int, Str] {
  let a = eval(left)?
  let b = eval(right)?
  if op == "+" {
    return Ok(a + b)
  }
  if op == "-" {
    return Ok(a - b)
  }
  if op == "*" {
    return Ok(a * b)
  }
  if b == 0 {
    return Err("division by zero")
  }
  return Ok(a / b)
}

fn eval(e: Ex) -> Result[Int, Str] {
  return match e {
    Ex.Num(value) => Ok(value),
    Ex.Neg(inner) => eval(inner).map(fn(v) => 0 - v),
    Ex.Bin(op, left, right) => eval_bin(op, left, right),
  }
}

pub fn calc(expr: Str) -> Result[Int, Str] {
  let toks = tokenize(expr)?
  let parsed = parse_expr(toks, 0)?
  if parsed.second != toks.len() {
    return Err("syntax error")
  }
  return eval(parsed.first)
}

